style.css:
@-moz-document domain("roblox.com") {
:root {
    --bbm-bg-dark: #050505;
    --bbm-card-dark: #0d0d0d;
    --bbm-border-red: #4a0000;
    --bbm-red-accent: #8b0000;
    --bbm-red-bright: #b22222;
    --bbm-text-light: #e0e0e0;
    --bbm-text-muted: #888888;
  }

  /* Main Backgrounds */
  body, 
  .light-theme, 
  .dark-theme,
  #container, 
  .content,
  .gui-container {
    background-color: var(--bbm-bg-dark) !important;
    color: var(--bbm-text-light) !important;
  }

  /* Navigation & Header */
  .navigation, 
  .navbar-fixed, 
  .rbx-header,
  #header {
    background-color: #000000 !important;
    border-bottom: 2px solid var(--bbm-red-accent) !important;
  }

  /* Cards, Boxes, and Containers */
  .rbx-box, 
  .dark-theme .rbx-box,
  div[class*="Card"], 
  div[class*="Container"],
  .modal-content,
  .item-card-container {
    background-color: var(--bbm-card-dark) !important;
    border: 1px solid var(--bbm-border-red) !important;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.9) !important;
  }

  /* Buttons (Buy, Play, Primary Actions) */
  .btn-primary-lg, 
  .btn-growth-lg,
  .btn-cta-md,
  button[class*="Button"]:not(.btn-control) {
    background-color: var(--bbm-red-accent) !important;
    color: #ffffff !important;
    font-weight: bold !important;
    border: 1px solid var(--bbm-red-bright) !important;
    border-radius: 4px !important;
    transition: background-color 0.2s ease, transform 0.1s ease !important;
  }

  .btn-primary-lg:hover, 
  .btn-growth-lg:hover,
  button[class*="Button"]:hover {
    background-color: var(--bbm-red-bright) !important;
    transform: translateY(-1px) !important;
  }

  /* Text & Links */
  h1, h2, h3, h4, .text-header, .font-bold {
    color: #ffffff !important;
  }

  a, .text-link {
    color: var(--bbm-red-bright) !important;
  }

  a:hover {
    color: #ff4d4d !important;
  }

  /* Inputs & Search Bars */
  input, textarea, .input-field {
    background-color: #121212 !important;
    color: var(--bbm-text-light) !important;
    border: 1px solid var(--bbm-border-red) !important;
  }

  input:focus, textarea:focus {
    border-color: var(--bbm-red-bright) !important;
    outline: none !important;
  }
}
